    dp=[0]*(n+2);dp[0]=1
    for j in range(n+1):
        if not dp[j]:continue
        v=dp[j];pj=P[j];mx=-1
        for i in range(j+1,n+2):
            p=P[i]
            if p<pj:
                if p>mx:
                    dp[i]=(dp[i]+v)%M
                    mx=p
    ans=dp[n+1]
    if any(P[i]<P[i+1] for i in range(1,n)):ans+=1
    print(ans%M)
