import sys,heapq
def main():
    d=sys.stdin.buffer.read().split();n,m,X=int(d[0]),int(d[1]),int(d[2])
    g=[[] for _ in range(2*n)]
    for i in range(m):
        u=int(d[3+2*i])-1;v=int(d[4+2*i])-1
        g[u].append(v);g[n+v].append(n+u)
    INF=1<<62;D=[INF]*(2*n);D[0]=0;h=[(0,0)]
    while h:
        c,x=heapq.heappop(h)
        if c>D[x]:continue
        for y in g[x]:
            if c+1<D[y]:D[y]=c+1;heapq.heappush(h,(c+1,y))
        y=x+n if x<n else x-n
        if c+X<D[y]:D[y]=c+X;heapq.heappush(h,(c+X,y))
    print(min(D[n-1],D[2*n-1]))
main()

