def main():
    d=sys.stdin.buffer.read().split();n=int(d[0]);A=list(map(int,d[1:n+1]))
    M=998244353;mx=max(A)
    phi=list(range(mx+1))
    for p in range(2,mx+1):
        if phi[p]==p:
            for k in range(p,mx+1,p):phi[k]-=phi[k]//p
    need=bytearray(mx+1)
    for a in A:need[a]=1
    dv=[[] for _ in range(mx+1)]
    for x in range(1,mx+1):
        for k in range(x,mx+1,x):
            if need[k]:dv[k].append(x)
    cache={}
    S=np.zeros(mx+1,np.int64)
    ans=0;p=1;out=[]
    for a in A:
        c=cache.get(a)
        if c is None:
            idx=np.array(dv[a],np.int64);c=(idx,np.array([phi[x] for x in dv[a]],np.int64));cache[a]=c
        idx,ph=c
        s=int(np.dot(S[idx],ph))%M
        ans=(2*ans+s)%M
        out.append(ans)
        S[idx]=(S[idx]+p)%M
        p=p*2%M
    print("\n".join(map(str,out)))
