def main():
    d=sys.stdin.buffer.read().split()
    n=int(d[0]);q=int(d[1])
    p=list(range(n+2));col=list(range(n+2));L=list(range(n+2));R=list(range(n+2));sz=[1]*(n+2)
    cnt=[1]*(n+2)
    def f(x):
        while p[x]!=x:
            p[x]=p[p[x]];x=p[x]
        return x
    out=[];i=2
    for _ in range(q):
        if d[i]==b'1':
            x=int(d[i+1]);c=int(d[i+2]);i+=3
