from typing import List
class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        by=[[] for _ in range(n+1)]
        for a,b in conflictingPairs:
            if a>b:a,b=b,a
            by[b].append(a)
        t1=t2=0
        bonus=[0]*(n+1)
        tot=0
        for r in range(1,n+1):
            for a in by[r]:
                if a>t1:t2=t1;t1=a
                elif a>t2:t2=a
            tot+=r-t1
            bonus[t1]+=t1-t2
        return tot+max(bonus)

