import itertools
def g(M,boxes):
    # state: per type (boxidx,fill) or None; boxes unlimited
    opts=[None]+[(i,f) for i,(v,p) in enumerate(boxes) for f in range(1,v+1)]
    states=list(itertools.combinations_with_replacement(range(len(opts)),M))
    val={s:0 for s in states}
    for it in range(300):
        nv={}
        for s in states:
            best=None
            for t in range(M):
                cur=opts[s[t]];ch=[0]
                for i,(v,p) in enumerate(boxes):
                    ns=list(s);ns[t]=opts.index((i,1));ch.append(1-p+val[tuple(sorted(ns))])
                if cur and cur[1]<boxes[cur[0]][0]:
                    ns=list(s);ns[t]=opts.index((cur[0],cur[1]+1));ch.append(1+val[tuple(sorted(ns))])
                m=max(ch);best=m if best is None else min(best,m)
            nv[s]=best
        val=nv
    return val[tuple([0]*M)]
