class Solution:
    def numberOfWays(self, n: int, x: int, y: int) -> int:
        M=10**9+7
        m=min(n,x)
        S=[1]+[0]*m
        for i in range(1,n+1):
            for j in range(min(i,m),0,-1):
                S[j]=(S[j-1]+j*S[j])%M
            S[0]=0
        r=0;p=1;yp=1
        for k in range(1,m+1):
            p=p*(x-k+1)%M;yp=yp*y%M
            r=(r+S[k]*p%M*yp)%M
        return r

