class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        M=10**9+7
        L=len(s)
        st=[0]*(L+2)
        for c in range(2,L+2):
            st[c]=st[bin(c).count('1')]+1
        C=[[0]*(L+1) for _ in range(L+1)]
        for i in range(L+1):
            C[i][0]=1
            for j in range(1,i+1):
                C[i][j]=(C[i-1][j-1]+C[i-1][j])%M
        cnt=[0]*(L+2)
        ones=0
        for i,ch in enumerate(s):
            if ch=='1':
                r=L-i-1
                for t in range(r+1):
                    cnt[ones+t]=(cnt[ones+t]+C[r][t])%M
                ones+=1
        return sum(cnt[c] for c in range(1,L+1) if st[c]<=k-1)%M

