    s=P*W+Q;seen[s]=1;cur=S[s]
    h=[]
    def push(c):
        i,j=divmod(c,W)
        if i>0 and not seen[c-W]:seen[c-W]=1;heapq.heappush(h,(S[c-W],c-W))
        if i<H-1 and not seen[c+W]:seen[c+W]=1;heapq.heappush(h,(S[c+W],c+W))
        if j>0 and not seen[c-1]:seen[c-1]=1;heapq.heappush(h,(S[c-1],c-1))
        if j<W-1 and not seen[c+1]:seen[c+1]=1;heapq.heappush(h,(S[c+1],c+1))
    push(s)
    while h and h[0][0]*X<cur:
        v,c=heapq.heappop(h);cur+=v;push(c)
    print(cur)
