from functools import lru_cache
def main(A):
    @lru_cache(None)
    def go(R,P,d):
        if not R or d==0: return 0
        m=min(R+P)&~1
        R=[x-m for x in R];P=[x-m for x in P]
        best=0
        for r in (0,1):
            c=sum(1 for b in P if (b+r)&1)
            nr=tuple(sorted((a+r)>>1 for a in R if not (a+r)&1))
            npp=tuple(sorted((a+r)>>1 for a in R if (a+r)&1))
            if not nr: v=c+max(sum(1 for b in npp if b&1),sum(1 for b in npp if not b&1))
            else: v=c+go(nr,npp,d-1)
            best=max(best,v)
        return best
    return go(tuple(A),(),75)
