def sol(N,M,K,X):
    P=998244353
    S=[[0]*(K+1) for _ in range(N+1)];S[0][0]=1
    for L in range(1,N+1):
        for k in range(1,K+1):S[L][k]=k*(S[L-1][k]+S[L-1][k-1])%P
    pw1=[pow(K-1,i,P) for i in range(N+1)];pw2=[pow(K-2,i,P) for i in range(N+1)]
    Ps=[0]*(N+1);Pd=[0]*(N+1);Pt=[S[L][K-1] for L in range(N+1)]
