        for di,dj in dirs:
            g=[[0]*m for _ in range(n)]
            ri=range(n) if di==1 else range(n-1,-1,-1)
            rj=range(m) if dj==1 else range(m-1,-1,-1)
            for i in ri:
                gi=grid[i]; row=g[i]; pi=i-di
                for j in rj:
                    v=gi[j]
                    if v==1: row[j]=1
                    else:
