        def add(s,i,v):
            s.tc+=1;s.ts+=v
            while i<=n:s.c[i]+=1;s.s[i]+=v;i+=i&-i
        def q(s,i):
            a=b=0
            while i>0:a+=s.c[i];b+=s.s[i];i-=i&-i
            return a,b
    FD=F();FU=F();off=0;on=0;base=0;Z=[]
