class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        m=(n+1)//2
        p=[1]*n
        for i in range(1,n):p[i]=p[i-1]*10%k
        w=[(p[i]+p[n-1-i])%k if i!=n-1-i else p[i] for i in range(m)]
        reach=[0]*(m+1)
        reach[m]=1
        for i in range(m-1,-1,-1):
            nb=0;nx=reach[i+1]
            for r in range(k):
                for d in range(10):
                    if nx>>((r+d*w[i])%k)&1:nb|=1<<r;break
            reach[i]=nb
        res=[];r=0
        for i in range(m):
            for d in range(9,-1,-1):
                t=(r+d*w[i])%k
                if reach[i+1]>>t&1:res.append(d);r=t;break
        s=''.join(map(str,res))
        return s+s[:n//2][::-1]

