from typing import List
from collections import deque
class Solution:
    def countNonDecreasingSubarrays(self, nums: List[int], k: int) -> int:
        n=len(nums);dq=deque();r=n-1;cost=0;ans=0
        for l in range(n-1,-1,-1):
            v=nums[l]
            while dq and nums[dq[0]]<=v:
                j=dq.popleft()
                end=dq[0] if dq else r+1
                cost+=(v-nums[j])*(end-j)
            dq.appendleft(l)
            while cost>k:
                cost-=nums[dq[-1]]-nums[r]
                if dq[-1]==r: dq.pop()
                r-=1
            ans+=r-l+1
        return ans

