        for k,(l,r) in enumerate(queries): byl.setdefault(l,[]).append((r,k))
        ans=[0]*len(queries)
        prev=[];bprev=[]
        for i in range(n-1,-1,-1):
            c=nums[i];b=c
            cur=[c];bc=[b]
            for j in range(len(prev)):
                c^=prev[j]
                p=bprev[j]
                if c>b:b=c
                if p>b:b=p
                cur.append(c);bc.append(b)
            prev=cur;bprev=bc
            if i in byl:
                for r,k in byl[i]: ans[k]=bc[r-i]
        return ans

