class Solution:
    def maximizeSumOfWeights(self, edges: List[List[int]], k: int) -> int:
        n=len(edges)+1
        adj=[[] for _ in range(n)]
        for u,v,w in edges:
            adj[u].append((v,w));adj[v].append((u,w))
        par=[-1]*n;pw=[0]*n;order=[0];seen=[False]*n;seen[0]=True
        for x in order:
            for y,w in adj[x]:
                if not seen[y]:
                    seen[y]=True;par[y]=x;pw[y]=w;order.append(y)
        dp0=[0]*n;dp1=[0]*n
        gains=[[] for _ in range(n)];base=[0]*n
        for v in reversed(order):
            g=gains[v];g.sort(reverse=True)
            s=base[v];a=s;b=s
            for i,x in enumerate(g):
                if x<=0:break
                if i<k:a+=x
                if i<k-1:b+=x
            dp0[v]=a;dp1[v]=b
            p=par[v]
            if p>=0:
                base[p]+=a;gains[p].append(pw[v]+b-a)
        return dp0[0]

