import sys
def main():
    d=sys.stdin.read().split()
    n,m,l=int(d[0]),int(d[1]),int(d[2])
    v=list(map(int,d[3:3+n+m+l]));K=n+m+l
    pw=[3**i for i in range(K)]
    s0=sum(pw[i] for i in range(n))+sum(2*pw[i] for i in range(n,n+m))
    less=[[j for j in range(K) if v[j]<v[i]] for i in range(K)]
    memo={}
    def moves(s,p):
        own=[(s//pw[i])%3 for i in range(K)]
        res=[]
        for i in range(K):
            if own[i]==p:
                b=s-p*pw[i]
                res.append(b)
                for j in less[i]:
                    if own[j]==0: res.append(b+p*pw[j])
        return res
    st=[(s0,1)]
    while st:
        s,p=st[-1]
        key=s*2+p-1
        if key in memo: st.pop();continue
        q=3-p;win=False;pend=[]
        for t in moves(s,p):
            r=memo.get(t*2+q-1)
            if r is None: pend.append((t,q))
            elif not r: win=True;break
        if win or not pend:
            memo[key]=win;st.pop()
        else: st.extend(pend)
    print("Takahashi" if memo[s0*2] else "Aoki")
main()

