        n=len(parent)
        ch=[[] for _ in range(n)]
        for i in range(1,n): ch[parent[i]].append(i)
        start=[0]*n; out=[]
        st=[(0,0)]
        while st:
            x,k=st.pop()
            if k==0: start[x]=len(out)
            if k<len(ch[x]):
                st.append((x,k+1)); st.append((ch[x][k],0))
            else:
                out.append(s[x])
        t='#'+'#'.join(out)+'#'
        m=len(t); d=[0]*m; l=0; r=-1
        for i in range(m):
            k=1 if i>r else min(d[l+r-i],r-i+1)
            while i-k>=0 and i+k<m and t[i-k]==t[i+k]: k+=1
            d[i]=k
            if i+k-1>r: l=i-k+1; r=i+k-1
        res=[False]*n
        sz=[1]*n
        order=[0]
        for x in order: order.extend(ch[x])
        for x in reversed(order):
            if x: sz[parent[x]]+=sz[x]
        for x in range(n):
            a=start[x]; b=a+sz[x]-1
            res[x]=d[a+b+1]-1>=sz[x]
        return res

