import sys,heapq
from collections import deque
def main():
    d=sys.stdin.buffer.read().split()
    n,m,S,T=int(d[0]),int(d[1]),int(d[2])-1,int(d[3])-1
    adj=[[] for _ in range(n)]
    V=2*n
    head=[-1]*V;to=[];cap=[];cost=[];nxt=[]
    def add(u,v,c,w):
        to.append(v);cap.append(c);cost.append(w);nxt.append(head[u]);head[u]=len(to)-1
        to.append(u);cap.append(0);cost.append(-w);nxt.append(head[v]);head[v]=len(to)-1
    for v in range(n):
        add(2*v,2*v+1,2 if v in(S,T) else 1,0)
    for i in range(m):
        u=int(d[4+2*i])-1;v=int(d[5+2*i])-1
        adj[u].append(v);adj[v].append(u)
        add(2*u+1,2*v,1,1);add(2*v+1,2*u,1,1)
    def bfs(s):
        D=[-1]*n;D[s]=0;q=deque([s])
        while q:
            x=q.popleft()
            for y in adj[x]:
                if D[y]<0:D[y]=D[x]+1;q.append(y)
        return D
    dS=bfs(S);dT=bfs(T)
    best=float('inf')
    for v in range(n):
        if len(adj[v])>=3:
            best=min(best,2*(dS[v]+dT[v])+2)
    src=2*S;snk=2*T+1
    INF=float('inf');pot=[0]*V;total=0;flow=0
    for _ in range(2):
        dist=[INF]*V;dist[src]=0;pe=[-1]*V;h=[(0,src)]
        while h:
            dd,x=heapq.heappop(h)
            if dd>dist[x]:continue
            e=head[x]
            while e!=-1:
                if cap[e]>0:
                    y=to[e];nd=dd+cost[e]+pot[x]-pot[y]
                    if nd<dist[y]:dist[y]=nd;pe[y]=e;heapq.heappush(h,(nd,y))
                e=nxt[e]
        if dist[snk]==INF:break
        for i in range(V):
            if dist[i]<INF:pot[i]+=dist[i]
        x=snk
        while x!=src:
            e=pe[x];cap[e]-=1;cap[e^1]+=1;total+=cost[e];x=to[e^1]
        flow+=1
    if flow==2:best=min(best,total)
    print(best if best<INF else -1)
main()

