class Solution:
    def minZeroArray(self, nums: List[int], queries: List[List[int]]) -> int:
        n=len(nums)
        masks=[(1<<(x+1))-1 for x in nums]
        b=[1]*n
        ok=lambda i:(b[i]>>nums[i])&1
        bad=sum(1 for i in range(n) if not ok(i))
        if bad==0: return 0
        for k,(l,r,v) in enumerate(queries):
            for i in range(l,r+1):
                if not ok(i):
                    b[i]=(b[i]|(b[i]<<v))&masks[i]
                    if ok(i): bad-=1
            if bad==0: return k+1
        return -1

