import heapq
class Solution:
    def minOperations(self, n: int, m: int) -> int:
        N=10000
        p=[True]*N;p[0]=p[1]=False
        for i in range(2,100):
            if p[i]:
                for j in range(i*i,N,i):p[j]=False
        if p[n] or p[m]:return -1
        L=len(str(n))
        d={n:n};h=[(n,n)]
        while h:
            c,u=heapq.heappop(h)
            if u==m:return c
            if d.get(u)!=c:continue
            pw=1
            for _ in range(L):
                dg=u//pw%10
                for dd in (-1,1):
                    if 0<=dg+dd<=9:
                        v=u+dd*pw
                        if not p[v]:
                            nc=c+v
                            if nc<d.get(v,1<<60):
                                d[v]=nc;heapq.heappush(h,(nc,v))
                pw*=10
        return -1

