class Solution:
    def maxActiveSectionsAfterTrade(self, s: str) -> int:
        ones = s.count('1')
        z = []
        i, n = 0, len(s)
        while i < n:
            j = i
            while j < n and s[j] == s[i]: j += 1
            if s[i] == '0': z.append(j - i)
            i = j
        best = 0
